-- Exact previous definitions. Use only after reviewing live candidate fingerprints; no business data rollback.
CREATE OR REPLACE FUNCTION public.org_workspace_read()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE c jsonb;super_ boolean;visible text[];assign_ text[];appoint_ text[];structure_ text[];history_ text[];configured boolean;BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) THEN RAISE EXCEPTION 'Vui lòng đăng nhập lại.';END IF;super_:=private.is_super_admin(auth.uid());c:=private.org_config(); SELECT coalesce(array_agg(id),'{}') INTO assign_ FROM org_units WHERE private.org_can(auth.uid(),'org.assign_staff',id); SELECT coalesce(array_agg(id),'{}') INTO appoint_ FROM org_units WHERE private.org_can(auth.uid(),'org.appoint_manager',id); SELECT coalesce(array_agg(id),'{}') INTO structure_ FROM org_units WHERE private.org_can(auth.uid(),'org.manage_structure',id); SELECT coalesce(array_agg(id),'{}') INTO history_ FROM org_units WHERE private.org_can(auth.uid(),'org.view_history',id); SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(private.base_rules(auth.uid(),c)) r WHERE r->>'permission' LIKE 'org.%') INTO configured; SELECT coalesce(array_agg(id),'{}') INTO visible FROM org_units WHERE super_ OR private.org_can(auth.uid(),'org.view',id) OR id=ANY(assign_||appoint_||structure_) OR NOT configured;
 c:=c||jsonb_build_object('units',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'units') x WHERE x->>'id'=ANY(visible)),'titles',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'titles') x WHERE super_ OR x->>'unit_id'=ANY(visible) OR (x->>'unit_id' IS NULL AND EXISTS(SELECT 1 FROM org_units u WHERE u.id=ANY(visible) AND (u.kind=x->>'unit_kind' OR (x->>'unit_kind'='individual' AND u.kind IN ('department','team')))))),'memberships',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'memberships') x WHERE x->>'unit_id'=ANY(visible) AND (super_ OR x->>'unit_id'=ANY(history_) OR ((x->>'active')::boolean AND (nullif(x->>'starts_at','') IS NULL OR (x->>'starts_at')::timestamptz<=now())))));
 IF NOT super_ THEN c:=c||jsonb_build_object('defaults','[]'::jsonb,'grants','[]'::jsonb,'bindings','[]'::jsonb,'bundles','[]'::jsonb);END IF;
 RETURN jsonb_build_object('revision',(SELECT revision FROM private.org_control WHERE id),'server_now',now(),'config',c,'staff',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',full_name,'status',status)),'[]') FROM profiles WHERE super_ OR cardinality(assign_||appoint_)>0 OR id IN (SELECT user_id FROM org_assignments WHERE unit_id=ANY(visible) AND (ends_at IS NULL OR ends_at>now()) AND (starts_at IS NULL OR starts_at<=now()))),'catalog',(SELECT coalesce(jsonb_agg(jsonb_build_object('key',key,'label',label,'module',module,'supported',private.base_supported(key))),'[]') FROM base_permission_catalog WHERE super_),'actor',jsonb_build_object('super',super_,'assign_all',super_,'appoint_all',super_,'assign_units',assign_,'appoint_units',appoint_,'structure_units',structure_,'view_history',cardinality(history_)>0,'history_units',history_),'events',(SELECT coalesce(jsonb_agg(to_jsonb(e)),'[]') FROM (SELECT * FROM org_events e WHERE super_ OR (jsonb_array_length(e.unit_ids)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(e.unit_ids) u WHERE NOT u=ANY(history_))) ORDER BY created_at DESC LIMIT 100)e));END $function$
;
CREATE OR REPLACE FUNCTION private.base_effective(u uuid, c jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE result jsonb:='[]';r record;d text;l jsonb;ok boolean;privileged boolean;active boolean;rules jsonb;BEGIN active:=private.is_active(u);privileged:=private.is_super_admin(u);rules:=private.base_rules(u,c);FOR r IN SELECT * FROM base_permission_catalog ORDER BY module,key LOOP d:=CASE WHEN private.base_supported(r.key) THEN CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key AND x->>'effect'='DENY') THEN 'DENY' WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key AND x->>'effect'='ALLOW') THEN 'ALLOW' ELSE 'NOT_CONFIGURED' END ELSE 'NOT_CONFIGURED' END;l:=private.base_legacy(u,r.key);ok:=active AND (privileged OR (r.key LIKE 'biz.crm_%' AND public.biz_admin(u)) OR CASE WHEN d='DENY' THEN false WHEN d='ALLOW' THEN true ELSE (l->>'allowed')::boolean END);result:=result||jsonb_build_array(jsonb_build_object('key',r.key,'label',r.label,'module',r.module,'allowed',ok,'decision',d,'bypass',privileged OR (r.key LIKE 'biz.crm_%' AND public.biz_admin(u)),'tier',CASE WHEN privileged OR (r.key LIKE 'biz.crm_%' AND public.biz_admin(u)) THEN 0 WHEN d<>'NOT_CONFIGURED' THEN 1 ELSE (l->'source'->>'tier')::int END,'legacy',l,'sources',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key),'[]'::jsonb),'supported',private.base_supported(r.key),'scope',CASE WHEN r.key LIKE 'biz.crm_%' AND d='ALLOW' THEN 'own' ELSE 'native' END,'conflict',EXISTS(SELECT 1 FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key AND x->>'effect'='ALLOW') AND EXISTS(SELECT 1 FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key AND x->>'effect'='DENY')));END LOOP;RETURN result;END $function$
;
CREATE OR REPLACE FUNCTION public.base_permissions_effective(_user uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE u uuid:=coalesce(_user,auth.uid());BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) OR (u<>auth.uid() AND NOT private.base_org_admin()) THEN RAISE EXCEPTION 'Không có quyền xem phân quyền.';END IF;RETURN jsonb_build_object('user_id',u,'revision',coalesce((SELECT revision FROM base_org_state WHERE id),0),'server_now',now(),'next_transition_at',private.base_next_transition(private.base_config()),'permissions',private.base_effective(u,private.base_config()));END $function$
;
